using CustomCodeFramework.Cqrs.Dispatching;using Dhole.Content.Api.Authorization;using Dhole.Content.Api.Extensions;using Dhole.Content.Application.Navigation.GetNavigationMenu;using Dhole.Content.Application.Navigation.SetNavigationMenuActive;using Dhole.Content.Application.Navigation.UpsertNavigationMenu;using Dhole.Content.Contracts.Navigation;namespace Dhole.Content.Api.Endpoints;public static class NavigationEndpoints{public static IEndpointRouteBuilder MapNavigationEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/content/menus").WithTags("Content Menus").RequireAuthorization();g.MapGet("/{location}",async(string location,string? siteKey,IQueryDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new GetNavigationMenuQuery(siteKey??"main",location),ct),h)).RequireScope(ContentScopeNames.View);g.MapPut("/{location}",async(string location,UpsertNavigationMenuRequest r,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new UpsertNavigationMenuCommand(r.Name,location,r.SiteKey,r.Items.Select(i=>new NavigationMenuItemInput(i.Label,i.Url,i.ContentId,i.ParentId,i.SortOrder,i.Target)).ToArray(),h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.SettingsEdit);g.MapPatch("/{id:guid}/active",async(Guid id,bool isActive,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new SetNavigationMenuActiveCommand(id,isActive,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.SettingsEdit);return app;}}
